windowclass.script:
function onInit()
	header.setValue(Interface.getString("tcwiz_head_characteristics"));
	sub_instructions.subwindow.setText(Interface.getString("tcwiz_steps_characteristics"));
	update();
end
function update()
	TCWizard.applyWallpaper(wallpaper, "tcwiz_art_characteristics");
	if sub_panel.subwindow then sub_panel.subwindow.update(); end
end

local STATS = { "str", "dex", "end", "int", "edu", "soc" };
function onInit()
	update();
end
function update()
	local S = TCWizard.getState();
	local tMods = TCWizard.getSpeciesMods();
	for _, s in ipairs(STATS) do
		self["score_" .. s].setValue(S.base[s] or 0);
		local n = tMods[s] or 0;
		self["species_" .. s].setValue(n ~= 0 and string.format("%+d", n) or "");
		local bHave = S.base[s] ~= nil;
		self["total_" .. s].setValue(bHave and tostring(TCWizard.getStat(s)) or "");
		self["mod_" .. s].setValue(bHave and string.format("DM %+d", TCWizard.getStatDM(s)) or "");
	end
	roll.setVisible(#S.rolls < 6 or TCWizard.canReroll());
	roll.setEnabled(not S.started);
	upp.setValue(#S.rolls == 6 and ("UPP " .. TCWizard.getUPP()) or "");
	startover.setVisible(TCWizard.isInProgress());
	hint.setValue(S.started and "Your careers have begun: the characteristics are set." or (#S.rolls == 6 and "Drag a rolled score onto another to swap them." or ""));
end

button_text.script:
local bArmed = false;
function onButtonPress()
	if not bArmed then
		bArmed = true;
		setText("Click again to confirm");
		return;
	end
	bArmed = false;
	setText("Start over");
	TCWizard.startOver();
end

windowclass.script:
function onInit()
	sub_instructions.subwindow.setText(Interface.getString("tcwiz_steps_species"));
	update();
end
function update()
	TCWizard.applyWallpaper(wallpaper, "tcwiz_art_species");
	local node = TCWizard.getSpeciesNode();
	local S = TCWizard.getState();
	list.closeAll();
	if not node then
		header.setValue("Choose a species");
		for _, n in ipairs(TCWizard.getSpeciesList()) do
			list.createWindow().setData(n);
		end
	else
		header.setValue(DB.getValue(node, "name", ""));
	end
	list.setVisible(node == nil);
	change.setVisible(node ~= nil and not S.started);
	local sMods = node and DB.getValue(node, "characteristics", "") or "";
	local t = {};
	if node then
		table.insert(t, "Characteristics: " .. (sMods ~= "" and sMods or "no changes"));
		for _, vTrait in ipairs(DB.getChildList(node, "traits")) do
			table.insert(t, DB.getValue(vTrait, "name", "") .. ": " .. DB.getValue(vTrait, "description", ""));
		end
		local sDesc = DB.getValue(node, "description", ""):gsub("</p>", "\n"):gsub("<[^>]+>", "");
		table.insert(t, "");
		table.insert(t, StringManager.trim(sDesc));
	end
	detail.setValue(table.concat(t, "\n"));
	detail.setVisible(node ~= nil);
end

function onInit()
	sub_instructions.subwindow.setText(Interface.getString("tcwiz_steps_background"));
	update();
end
function update()
	TCWizard.applyWallpaper(wallpaper, "tcwiz_art_background");
	local S = TCWizard.getState();
	local nChosen, nAllowed = TCWizard.getBackgroundCounts();
	if #S.rolls < 6 then
		header.setValue("Background skills (roll your characteristics first)");
	else
		header.setValue(string.format("Background skills: %d of %d (EDU DM + 3)", nChosen, nAllowed));
	end
	list.closeAll();
	for _, s in ipairs(TCData.BACKGROUND_SKILLS) do
		list.createWindow().setData("background", s, s .. " 0", S.bg[s] == true, S.started);
	end
	if entry_homeworld.getValue() ~= (S.homeworld or "") then entry_homeworld.setValue(S.homeworld or ""); end
end

function onInit()
	sub_instructions.subwindow.setText(Interface.getString("tcwiz_steps_careers"));
	update();
end
function update()
	TCWizard.applyWallpaper(wallpaper, "tcwiz_art_careers");
	local S = TCWizard.getState();
	if not TCWizard.isReadyForCareers() then
		status.setValue("Roll your characteristics and choose a species first.");
	else
		local v = TCWizard.curVisit();
		local s = string.format("Age %d, %d term(s) served.  UPP %s.", TCWizard.getAge(), #S.terms, TCWizard.getUPP());
		if v then
			s = s .. string.format("  Now: %s (%s), rank %s%d %s", TCData.CAREERS[v.key].name, TCWizard.getAssignment(v).name, v.officer and "O" or "", v.officer and v.orank or v.rank, TCWizard.getRankTitle(v));
		end
		status.setValue(s);
	end
	if sub_card.subwindow then sub_card.subwindow.update(); end
	sub_card.setVisible(TCWizard.isReadyForCareers());
	local tSum = {};
	local sSkills = TCWizard.getSkillListText();
	table.insert(tSum, "Skills: " .. (sSkills ~= "" and sSkills or "none yet"));
	local sAssoc = TCWizard.getAssocText();
	if sAssoc ~= "" then table.insert(tSum, sAssoc); end
	local sCareers = TCWizard.getCareerSummary();
	if sCareers ~= "" then table.insert(tSum, sCareers); end
	if S.cash > 0 then table.insert(tSum, string.format("Cash: Cr%d", S.cash)); end
	local sBen = TCWizard.getBenefitsText();
	if sBen ~= "" then table.insert(tSum, sBen); end
	summary.setValue(table.concat(tSum, "\n"));
	logtext.setValue(TCWizard.getLogText());
end

function onInit()
	sub_instructions.subwindow.setText(Interface.getString("tcwiz_steps_benefits"));
	update();
end
function update()
	TCWizard.applyWallpaper(wallpaper, "tcwiz_art_benefits");
	local S = TCWizard.getState();
	local t = {};
	table.insert(t, string.format("Cash from mustering out: Cr%d (%d of 3 cash rolls used)", S.cash, S.cashRolls));
	for _, d in ipairs(S.debts) do table.insert(t, string.format("  less Cr%d for %s", d.amount, d.what)); end
	local nFinal = TCWizard.getFinalCash();
	table.insert(t, nFinal >= 0 and string.format("Cash at the start of play: Cr%d", nFinal) or string.format("Debt at the start of play: Cr%d", -nFinal));
	if S.shares > 0 then table.insert(t, string.format("Ship Shares: %d (each worth MCr1 towards a ship; Cr1000 a year if not used)", S.shares)); end
	if S.pension > 0 then table.insert(t, string.format("Pension: Cr%d a year", S.pension)); end
	if S.tas then table.insert(t, "TAS Membership"); end
	for _, b in ipairs(S.benefits) do
		if b.kind == "ship" then
			table.insert(t, b.ship .. (b.mortgage and string.format(": %d%% of the mortgage paid; roll 1D times on the Spacecraft Quirks Table", b.paid) or ""));
		end
	end
	summary.setValue(table.concat(t, "\n"));
	items.closeAll();
	local nItems = 0;
	for i, b in ipairs(S.benefits) do
		if b.kind == "item" then
			items.createWindow().setData(i, b);
			nItems = nItems + 1;
		end
	end
	header_items.setVisible(nItems > 0);
	medical.closeAll();
	for i, inj in ipairs(S.injuries) do
		medical.createWindow().setData(i, inj);
	end
	header_medical.setVisible(#S.injuries > 0);
end

local _bSetting = false;
function onInit()
	sub_instructions.subwindow.setText(Interface.getString("tcwiz_steps_skills"));
	_bSetting = true;
	pkgcombo.add("", "(none)");
	for _, p in ipairs(TCData.SKILL_PACKAGES) do pkgcombo.add(p.name, p.name); end
	for _, cSkill in ipairs({ conn_skill1, conn_skill2 }) do
		cSkill.add("", "(choose a skill)");
		for _, s in ipairs(TCData.ALL_SKILLS) do
			if s ~= "Jack-of-all-Trades" then cSkill.add(s, s); end
		end
	end
	_bSetting = false;
	update();
end
function update()
	TCWizard.applyWallpaper(wallpaper, "tcwiz_art_skills");
	local S = TCWizard.getState();
	local tTask = TCWizard.getTask();
	sub_card.setVisible(S.done and (tTask ~= nil or S.waiting ~= nil));
	if sub_card.subwindow then sub_card.subwindow.update(); end
	local sSkills = TCWizard.getSkillListText();
	skills.setValue((sSkills ~= "" and sSkills or "No skills yet.") .. string.format("\n\nTotal levels %d of %d (3 x (INT + EDU)).", TCWizard.getTotalSkillLevels(), TCWizard.getSkillLimit()));
	for i = 1, 2 do
		local c = S.connections[i] or {};
		local cDone = self["conn_done" .. i];
		cDone.setValue(c.applied and ("Taken: " .. (c.skill or "")) or "");
		self["conn_apply" .. i].setVisible(S.done and not c.applied);
	end
	_bSetting = true;
	if pkgcombo.getValue() ~= (S.package or "") then pkgcombo.setValue(S.package or ""); end
	_bSetting = false;
	pkgskills.closeAll();
	local p = TCWizard.getPackage();
	pkgtext.setValue(p and p.text or "");
	if p then
		for i, sSkill in ipairs(p.skills) do
			local v = S.packagePicks[i];
			pkgskills.createWindow().setData("package", i, sSkill .. (v == "applied" and "  (taken)" or ""), v ~= nil, v == "applied" or not S.done);
		end
	end
	pkgapply.setVisible(S.done and p ~= nil);
end
function onPackage(sValue)
	if _bSetting then return; end
	TCWizard.setPackage(sValue);
end

function onInit()
	sub_instructions.subwindow.setText(Interface.getString("tcwiz_steps_finish"));
	update();
end
function update()
	TCWizard.applyWallpaper(wallpaper, "tcwiz_art_finish");
	local S = TCWizard.getState();
	for _, k in ipairs({ "name", "gender", "homeworld", "appearance", "why" }) do
		local c = self["entry_" .. k];
		if c and c.getValue() ~= (S[k] or "") then c.setValue(S[k] or ""); end
	end
	warnings.closeAll();
	for _, s in ipairs(TCWizard.getAllWarnings()) do
		warnings.createWindow().text.setValue(s);
	end
	header_warn.setVisible(warnings.getWindowCount() > 0);
	local t = {};
	table.insert(t, string.format("UPP %s, age %d", TCWizard.getUPP(), TCWizard.getAge()));
	local node = TCWizard.getSpeciesNode();
	if node then table.insert(t, "Species: " .. DB.getValue(node, "name", "")); end
	local sC = TCWizard.getCareerSummary();
	if sC ~= "" then table.insert(t, sC); end
	table.insert(t, "Skills: " .. TCWizard.getSkillListText());
	local sA = TCWizard.getAssocText();
	if sA ~= "" then table.insert(t, sA); end
	local sB = TCWizard.getBenefitsText();
	if sB ~= "" then table.insert(t, sB); end
	local n = TCWizard.getFinalCash();
	table.insert(t, n >= 0 and string.format("Cash: Cr%d", n) or string.format("Debt: Cr%d", -n));
	summary.setValue(table.concat(t, "\n"));
end
